COMMENT ON COLUMN recon_exception.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_recon_exception_tenant ON recon_exception (tenant_id, created_at);
CREATE INDEX ix_recon_exception_recon_run_id ON recon_exception (recon_run_id);
CREATE INDEX ix_recon_exception_external_record_id ON recon_exception (external_record_id);
CREATE INDEX ix_recon_exception_internal_entry_id ON recon_exception (internal_entry_id);
CREATE INDEX ix_recon_exception_assigned_to ON recon_exception (assigned_to);
ALTER TABLE recon_exception ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON recon_exception USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_recon_exception_touch BEFORE UPDATE ON recon_exception FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA recon TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA recon TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA recon GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
